function.arguments:
{"path": "kms.tf", "content": "resource "aws_kms_key" "example" {
  description             = var.kms_description
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect    = "Allow",
        Principal = "*",
        Action    = "kms:*",
        Resource    = "*"
      }
    ]
  })
}

output "kms_key_id" {
  value = aws_kms_key.example.id
}
"}

